<?php
declare(strict_types=1);
namespace Core\I18n;
use Core\Database\Connection;
final class ContentTranslations{
 public function __construct(private Connection $db){}
 public static function locale(string $value):string{$v=strtolower(str_replace('_','-',trim($value)));return preg_match('/^[a-z]{2}(?:-[a-z]{2})?$/',$v)?$v:'';}
 public function languages():array{return $this->db->fetchAll('SELECT * FROM `'.$this->db->table('site_languages').'` WHERE active=1 ORDER BY name');}
 public function addLanguage(string $locale,string $name):?string{$locale=self::locale($locale);$name=trim(strip_tags($name));if($locale===''||$name==='')return'Use a valid locale such as fr or es-mx and enter a language name.';try{$this->db->insert('site_languages',['locale'=>$locale,'name'=>mb_substr($name,0,80),'active'=>1,'created_at'=>date('Y-m-d H:i:s')]);}catch(\Throwable){$this->db->update('site_languages',['name'=>mb_substr($name,0,80),'active'=>1],'locale = ?',[$locale]);}return null;}
 public function save(int $pageId,string $locale,array $data):?string{$locale=self::locale($locale);$page=$this->db->fetch('SELECT id FROM `'.$this->db->table('pages').'` WHERE id=?',[$pageId]);$title=trim(strip_tags((string)($data['title']??'')));$slug=trim(strtolower(preg_replace('/[^a-z0-9]+/','-',(string)($data['slug']??''))),'-');if(!$page||$locale===''||$title===''||$slug==='')return'Page, locale, title and slug are required.';$row=['page_id'=>$pageId,'locale'=>$locale,'slug'=>$slug,'title'=>mb_substr($title,0,190),'body'=>(new \Core\Content\Sanitizer())->html((string)($data['body']??'')),'blocks_json'=>(string)($data['blocks_json']??'[]'),'meta_title'=>mb_substr(strip_tags((string)($data['meta_title']??'')),0,190),'meta_description'=>mb_substr(strip_tags((string)($data['meta_description']??'')),0,500),'schema_json'=>$data['schema_json']??null,'updated_at'=>date('Y-m-d H:i:s')];$existing=$this->db->fetch('SELECT id FROM `'.$this->db->table('page_translations').'` WHERE page_id=? AND locale=?',[$pageId,$locale]);try{if($existing)$this->db->update('page_translations',$row,'id = ?',[(int)$existing['id']]);else{$row['created_at']=date('Y-m-d H:i:s');$this->db->insert('page_translations',$row);}}catch(\Throwable){return'That translated slug is already used in this language.';}return null;}
 public function forPage(int $pageId,string $locale):?array{return $this->db->fetch('SELECT * FROM `'.$this->db->table('page_translations').'` WHERE page_id=? AND locale=?',[$pageId,self::locale($locale)]);}
 public function findPublished(string $locale,string $slug):?array{$row=$this->db->fetch('SELECT p.*,t.locale,t.slug translated_slug,t.title translated_title,t.body translated_body,t.blocks_json translated_blocks_json,t.meta_title translated_meta_title,t.meta_description translated_meta_description,t.schema_json translated_schema_json FROM `'.$this->db->table('page_translations').'` t JOIN `'.$this->db->table('pages').'` p ON p.id=t.page_id WHERE t.locale=? AND t.slug=? AND p.status=\'published\' AND p.deleted_at IS NULL',[self::locale($locale),$slug]);if(!$row)return null;foreach(['slug','title','body','blocks_json','meta_title','meta_description','schema_json'] as $field)$row[$field]=$row['translated_'.$field]??$row[$field]??null;return $row;}
 public function translatedNav(string $locale):array{return $this->db->fetchAll('SELECT t.slug,t.title FROM `'.$this->db->table('page_translations').'` t JOIN `'.$this->db->table('pages').'` p ON p.id=t.page_id WHERE t.locale=? AND p.status=\'published\' AND p.deleted_at IS NULL ORDER BY t.title',[$locale]);}
 public function alternates(int $pageId):array{return $this->db->fetchAll('SELECT t.locale,t.slug,t.title,l.name FROM `'.$this->db->table('page_translations').'` t JOIN `'.$this->db->table('site_languages').'` l ON l.locale=t.locale AND l.active=1 WHERE t.page_id=? ORDER BY l.name',[$pageId]);}
}
